
const chokidar = require('chokidar');
let eventBuffer = {};

var interval = 300

function watchFiles(paths) {
    const watcher = chokidar.watch(paths, {
        persistent: true,
        ignoreInitial: true
    });


    watcher.on('all', (event, path) => {
        eventBuffer[path] = event;
    });
}

var eventCallback;
var readyCallback;

// 启动循环, 清空缓冲区, 并抛出所有缓存
setInterval(() => {
    if (Object.keys(eventBuffer).length > 0) {
        const events = { ...eventBuffer };
        eventBuffer = {};
        if (eventCallback) {
            eventCallback(events);
        }
    }
}, interval);



module.exports = {
    watchFiles: function (paths) {
        watchFiles(paths);
    },
    registerEventCallback: function (callback) {
        eventCallback = callback;
    },
    registerReadyCallback: function (callback) {
        readyCallback = callback;
    }
};
